/**
 * A utility component that allows messages to be programmatically broadcast to assistive technologies.
 *
 * - {@link https://livingdesign.walmart.com/utilities/a11y-announcement/react/ React documentation}
 *
 * ### A11yAnnouncementProvider
 *
 * Add the provider or the [Living Design Provider](https://livingdesign.walmart.com/utilities/living-design-provider/react) to your application's root. The provider must be in the DOM on page load to provide assistive technology announcement. It cannot be added dynamically.
 *
 * ```tsx
 * import * as React from "react";
 * import * as ReactDOM from "react-dom";
 * import {A11yAnnouncementProvider} from "@walmart-web/livingdesign-components";
 *
 * import {App} from "./App";
 *
 * ReactDOM.render(
 *   <A11yAnnouncementProvider>
 *     <App />
 *   </A11yAnnouncementProvider>,
 *   document.getElementById("root"),
 * );
 * ```
 *
 * ### useA11yAnnouncement
 *
 * Consume the provider via the hook. The hook provides two APIs:
 *
 * - `announceAssertive(annoucement: string)`: This should only be used for time-sensitive/critical notifications that absolutely require the user's immediate attention.
 * - `announcePolite(announcement: string)`: The screen reader will speak changes whenever the user is idle.
 *
 * ```tsx
 * import * as React from "react";
 * import {
 *   Button,
 *   useA11yAnnouncement,
 * } from "@walmart-web/livingdesign-components";
 *
 * export const MyComponent = () => {
 *   const {announceAssertive} = useA11yAnnouncement();
 *
 *   return (
 *     <Button
 *       onClick={() => {
 *         const date = new Date();
 *
 *         announceAssertive(`The time is: ${date.toLocaleTimeString()}`);
 *       }}
 *       variant="primary"
 *     >
 *       Make Announcement
 *     </Button>
 *   );
 * };
 * ```
 */
